func ResourceApihubAddonFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("name", flattenApihubAddonName(res["name"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("display_name", flattenApihubAddonDisplayName(res["displayName"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("description", flattenApihubAddonDescription(res["description"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("data_source", flattenApihubAddonDataSource(res["dataSource"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("create_time", flattenApihubAddonCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("update_time", flattenApihubAddonUpdateTime(res["updateTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("state", flattenApihubAddonState(res["state"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("boost_spec_gemini_region_id", flattenApihubAddonBoostSpecGeminiRegionId(res["boostSpecGeminiRegionId"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}
	if err = d.Set("config", flattenApihubAddonConfig(res["config"], d, config)); err != nil {
		return fmt.Errorf("Error reading Addon: %s", err)
	}

	return nil
}
